// Prepare health check payload
return {
  check_id: `health-${Date.now()}`,
  timestamp: new Date().toISOString(),
  services: ['supabase', 'anthropic', 'openai', 'deepseek', 'qdrant', 'fallai', 'resend', 'apify', 'google_places'],
  results: {}
};

// Determine which service to check
const services = $input.first().json;
const service = services.service || services;

const checks = {
  'supabase': { method: 'GET', url: `${$vars.SUPABASE_URL}/rest/v1/`, headers: { apikey: $vars.SUPABASE_ANON_KEY }, name: 'Supabase DB' },
  'anthropic': { method: 'GET', url: 'https://api.anthropic.com/v1/models', headers: { 'x-api-key': $vars.ANTHROPIC_API_KEY }, name: 'Claude API' },
  'openai': { method: 'GET', url: 'https://api.openai.com/v1/models', headers: { Authorization: `Bearer ${$vars.OPENAI_API_KEY}` }, name: 'OpenAI API' },
  'deepseek': { method: 'GET', url: 'https://api.deepseek.com/v1/models', headers: { Authorization: `Bearer ${$vars.DEEPSEEK_API_KEY}` }, name: 'DeepSeek API' },
  'qdrant': { method: 'GET', url: `${$vars.QDRANT_URL}/health`, headers: { 'api-key': $vars.QDRANT_API_KEY }, name: 'Qdrant Vector DB' },
  'fallai': { method: 'GET', url: 'https://queue.fal.run/fal-ai/flux/dev/health', headers: { Authorization: `Key ${$vars.FAL_KEY}` }, name: 'Fall AI' },
  'resend': { method: 'GET', url: 'https://api.resend.com/health', headers: { Authorization: `Bearer ${$vars.RESEND_API_KEY}` }, name: 'Resend Email' },
  'apify': { method: 'GET', url: 'https://api.apify.com/v2/users/me', headers: { Authorization: `Bearer ${$vars.APIFY_API_KEY}` }, name: 'Apify Scraper' },
  'google_places': { method: 'GET', url: `https://maps.googleapis.com/maps/api/place/health?key=${$vars.GOOGLE_API_KEY}`, headers: {}, name: 'Google Places' }
};

const check = checks[service] || checks['supabase'];

return {
  service: service,
  name: check.name,
  method: check.method,
  url: check.url,
  headers: check.headers,
  check_id: $('Prepare Health Check').first().json.check_id
};

// Evaluate health result
const response = $input.first().json;
const serviceData = $('Prepare Service Check').first().json;
const statusCode = response.statusCode || response.status || 200;
const isHealthy = statusCode >= 200 && statusCode < 500;
const responseTime = response.responseTime || 0;

return {
  service: serviceData.service,
  name: serviceData.name,
  status: isHealthy ? 'healthy' : 'degraded',
  response_time_ms: responseTime,
  status_code: statusCode,
  check_id: serviceData.check_id,
  checked_at: new Date().toISOString()
};

// Aggregate all service results
const allChecks = $input.all();
const checkId = allChecks[0]?.json?.check_id || `health-${Date.now()}`;

const healthy = allChecks.filter(c => c.json.status === 'healthy').length;
const degraded = allChecks.filter(c => c.json.status === 'degraded').length;
const totalServices = allChecks.length;
const healthScore = Math.round((healthy / totalServices) * 100);

let overallStatus = 'healthy';
if (healthScore < 70) overallStatus = 'critical';
else if (healthScore < 100) overallStatus = 'degraded';

const degradedServices = allChecks.filter(c => c.json.status === 'degraded').map(c => ({
  service: c.json.service,
  name: c.json.name,
  status_code: c.json.status_code
}));

return {
  check_id: checkId,
  overall_status: overallStatus,
  health_score: healthScore,
  total_services: totalServices,
  healthy_services: healthy,
  degraded_services: degraded,
  degraded_list: degradedServices,
  services_detail: allChecks.map(c => ({ service: c.json.service, name: c.json.name, status: c.json.status, response_time: c.json.response_time_ms })),
  checked_at: new Date().toISOString()
};

// Health report for anomaly table
const report = $input.first().json;

return {
  flow_id: 'N8N-S01',
  check_id: report.check_id,
  overall_status: report.overall_status,
  health_score: report.health_score,
  degraded_services: report.degraded_list,
  checked_at: report.checked_at
};

// Prepare anomaly alert for degraded services
const report = $input.first().json;

return {
  flow_id: 'N8N-S01',
  anomaly_type: 'pipeline_degraded',
  details: {
    check_id: report.check_id,
    health_score: report.health_score,
    degraded_services: report.degraded_services || report.degraded_list,
    message: `${report.degraded_services || 0} service(s) degraded`
  },
  severity: report.overall_status === 'critical' ? 'CRITICAL' : 'WARNING',
  created_at: report.checked_at || new Date().toISOString()
};
